<?php $flash = get_flash(); if ($flash): ?><div class="flash-popup <?=e($flash['type'])?>" id="flashPopup"><span><?=e($flash['message'])?></span><button onclick="document.getElementById('flashPopup').remove()">×</button></div><style>.flash-popup{position:fixed;top:24px;right:24px;z-index:1000;min-width:280px;padding:15px 18px;border-radius:8px;color:#fff;box-shadow:0 8px 25px #0003;display:flex;justify-content:space-between;gap:18px;align-items:center;font:14px Arial}.flash-popup.success{background:#16a34a}.flash-popup.error{background:#dc2626}.flash-popup button{background:transparent;border:0;color:#fff;font-size:22px;cursor:pointer}</style><script>setTimeout(function(){const p=document.getElementById('flashPopup');if(p)p.remove()},4000)</script><?php endif; ?>
